{
  "spec": "This plan adds optional due dates (YYYY-MM-DD) to tasks, supporting `add --due`, `done`, and `overdue` commands. Due dates are persisted in the JSON storage, ensuring backward compatibility with existing files that lack due dates. The `list` command displays due dates when present, and `overdue` filters for incomplete tasks past their due date. The implementation updates the Task model, storage layer, CLI, and rendering logic.",
  "stack": "Python, standard library (json, datetime, argparse), pytest",
  "tasks": [
    {
      "id": 1,
      "title": "Add optional due_date field to Task model and ensure backward compatibility",
      "files": [
        "todo/model.py"
      ],
      "test": "tests/test_todo.py: test_model_defaults checks that Task() creates a task with due_date=None and Task(text='x', due_date='2023-01-01') sets it correctly."
    },
    {
      "id": 2,
      "title": "Update storage to handle tasks with and without due dates",
      "files": [
        "todo/storage.py"
      ],
      "test": "tests/test_todo.py: test_storage_roundtrip checks that saving a task with a due date and loading it preserves the date, and saving a task without a due date and loading it results in None."
    },
    {
      "id": 3,
      "title": "Add --due argument to the add command in CLI",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_add_with_due checks that `add 'Buy milk' --due 2023-12-31` creates a task with the specified due date."
    },
    {
      "id": 4,
      "title": "Add done command to mark a task as completed",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_done_task checks that `done 1` marks the first task as done and subsequent list/overdue commands reflect this state."
    },
    {
      "id": 5,
      "title": "Implement overdue command to list incomplete past-due tasks",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_overdue_checks checks that `overdue` lists only tasks that are not done and have a due date before today, sorted by due date."
    },
    {
      "id": 6,
      "title": "Update render function to display due dates in list output",
      "files": [
        "todo/listing.py"
      ],
      "test": "tests/test_todo.py: test_list_shows_due_date checks that `list` output includes the due date in YYYY-MM-DD format for tasks that have one."
    },
    {
      "id": 7,
      "title": "Ensure backward compatibility for loading old JSON files without due dates",
      "files": [
        "todo/storage.py"
      ],
      "test": "tests/test_todo.py: test_old_file_loads checks that loading a JSON file with tasks missing the 'due_date' field results in tasks with due_date=None."
    }
  ]
}

