      "check": "python -c \"from todo.storage import save, load; from todo.model import Task; save('t.json', [Task(id=1, text='x', due_date='2023-01-01')]); print(load('t.json')[0].due_date)\"",
      "expect": "2023-01-01"
    },
    {
      "id": 3,
      "title": "Add --due argument to the add command in CLI",
