      "check": "python -c \"from todo import cli; cli.main(['add', 'Buy milk', '--due', '2023-12-31'], 't.json'); from todo.storage import load; print(load('t.json')[0].due_date)\"",
      "expect": "2023-12-31"
    },
    {
      "id": 4,
      "title": "Add done command to mark a task as completed",
