      "check": "python -c \"from todo import cli; cli.main(['add', 'Task 1'], 't.json'); cli.main(['done', '1'], 't.json'); print(cli.main(['list'], 't.json'))\"",
      "expect": "1 [x] Task 1"
    },
    {
      "id": 5,
      "title": "Implement overdue command to list incomplete past-due tasks",
