      "check": "python -c \"from todo import cli; cli.main(['add', 'Task 1', '--due', '2020-01-01'], 't.json'); print(cli.main(['overdue'], 't.json'))\"",
      "expect": "1 [ ] Task 1"
    },
    {
      "id": 6,
      "title": "Update render function to display due dates in list output",
